import PQueue from 'p-queue';
import type { Logger } from 'pino';
import type { RetryConfig } from './types.js';
import type { SessionManager } from './session.js';
import type { AuthManager } from './auth.js';

/**
 * HTTP client with cookie handling, retries, and rate limiting
 */
export class HttpClient {
  private session: SessionManager;
  private auth: AuthManager | null;
  private baseUrl: string;
  private headers: Record<string, string>;
  private retryConfig: Required<RetryConfig>;
  private logger: Logger;
  private queue: PQueue;

  constructor(
    baseUrl: string,
    session: SessionManager,
    auth: AuthManager | null,
    headers: Record<string, string>,
    retryConfig: Required<RetryConfig>,
    rateLimit: { concurrency: number; intervalMs: number },
    logger: Logger
  ) {
    this.baseUrl = baseUrl;
    this.session = session;
    this.auth = auth;
    this.headers = headers;
    this.retryConfig = retryConfig;
    this.logger = logger;

    // Configure rate limiting queue
    this.queue = new PQueue({
      concurrency: rateLimit.concurrency,
      interval: rateLimit.intervalMs,
      intervalCap: 1,
    });
  }

  /**
   * Execute request with authentication, retries, and rate limiting
   */
  async requestWithAuth<T = any>(
    path: string,
    options: RequestInit = {}
  ): Promise<T> {
    return this.queue.add(() => this.executeRequest<T>(path, options, 0, false)) as Promise<T>;
  }

  /**
   * Internal method to execute a request with retry logic
   */
  private async executeRequest<T>(
    path: string,
    options: RequestInit,
    attempt: number,
    isRetry: boolean
  ): Promise<T> {
    const url = new URL(path, this.baseUrl).toString();
    
    // Get cookies from jar
    const jar = this.session.getJar();
    const cookieHeader = await jar.getCookieString(url);

    const requestHeaders = {
      ...this.headers,
      'Origin': this.baseUrl,
      'Referer': new URL('/app', this.baseUrl).toString(),
      ...options.headers,
      ...(cookieHeader ? { Cookie: cookieHeader } : {}),
    };

    this.logger.debug(
      { url, method: options.method || 'GET', attempt, isRetry },
      'Executing request'
    );

    let response: Response;
    try {
      response = await fetch(url, {
        ...options,
        headers: requestHeaders,
      });

      // Store cookies from response
      const setCookies = response.headers.getSetCookie?.() || [];
      for (const cookie of setCookies) {
        await jar.setCookie(cookie, url);
      }
      if (setCookies.length > 0) {
        await this.session.save();
      }
    } catch (err: any) {
      this.logger.error({ err, url, attempt }, 'Request failed with network error');
      
      // Retry on network errors
      if (attempt < this.retryConfig.maxRetries) {
        const delay = this.calculateDelay(attempt);
        this.logger.info({ delay, attempt }, 'Retrying after network error');
        await this.sleep(delay);
        return this.executeRequest<T>(path, options, attempt + 1, true);
      }
      
      throw err;
    }

    // Parse response body
    let body: any;
    const contentType = response.headers.get('content-type') || '';
    if (contentType.includes('application/json')) {
      body = await response.json();
    } else {
      body = await response.text();
    }

    // Check for session expiry and relogin if needed
    if (this.auth && !isRetry && this.auth.isSessionExpired(response, body)) {
      this.logger.warn('Session expired detected, attempting relogin');
      await this.auth.reloginIfNeeded();
      
      // Retry the request once after relogin
      return this.executeRequest<T>(path, options, 0, true);
    }

    // Handle rate limiting (429)
    if (response.status === 429) {
      if (attempt < this.retryConfig.maxRetries) {
        const retryAfter = response.headers.get('Retry-After');
        const delay = retryAfter
          ? parseInt(retryAfter) * 1000
          : this.calculateDelay(attempt);
        
        this.logger.warn({ delay, attempt, retryAfter }, 'Rate limited, retrying');
        await this.sleep(delay);
        return this.executeRequest<T>(path, options, attempt + 1, true);
      }
    }

    // Handle 5xx errors with retry
    if (response.status >= 500 && response.status < 600) {
      if (attempt < this.retryConfig.maxRetries) {
        const delay = this.calculateDelay(attempt);
        this.logger.warn({ status: response.status, delay, attempt }, 'Server error, retrying');
        await this.sleep(delay);
        return this.executeRequest<T>(path, options, attempt + 1, true);
      }
    }

    // Check for success
    if (!response.ok) {
      const error = new Error(
        `HTTP ${response.status}: ${response.statusText}\n${typeof body === 'string' ? body : JSON.stringify(body, null, 2)}`
      );
      this.logger.error({ status: response.status, body }, 'Request failed');
      throw error;
    }

    this.logger.debug({ status: response.status }, 'Request successful');
    return body as T;
  }

  /**
   * Calculate delay with exponential backoff and jitter
   */
  private calculateDelay(attempt: number): number {
    const exponentialDelay = this.retryConfig.baseDelayMs * Math.pow(2, attempt);
    const jitter = Math.random() * this.retryConfig.baseDelayMs;
    return Math.min(exponentialDelay + jitter, 30000); // Cap at 30 seconds
  }

  /**
   * Sleep utility
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * POST request helper
   */
  async post<T = any>(path: string, body: any): Promise<T> {
    return this.requestWithAuth<T>(path, {
      method: 'POST',
      body: JSON.stringify(body),
    });
  }

  /**
   * GET request helper
   */
  async get<T = any>(path: string): Promise<T> {
    return this.requestWithAuth<T>(path, {
      method: 'GET',
    });
  }
}
