#!/usr/bin/env node

import { Command } from 'commander';
import { readFile, writeFile, mkdir } from 'fs/promises';
import { createInterface } from 'readline';
import { ProspectClient } from './index.js';
import type { ClientConfig, SearchPayload } from './types.js';
import { dirname } from 'path';

const program = new Command();

/**
 * Prompt for password from stdin
 */
async function promptPassword(prompt: string): Promise<string> {
  const rl = createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  return new Promise((resolve) => {
    rl.question(prompt, (answer) => {
      rl.close();
      resolve(answer);
    });
  });
}

/**
 * Get credentials from env or prompt
 */
async function getCredentials(): Promise<{ username: string; password: string }> {
  let username = process.env.PROSPECT_USER || process.env.PROSPECT_EMAIL;
  let password = process.env.PROSPECT_PASS;

  if (!username) {
    username = await promptPassword('Email: ');
  }

  if (!password) {
    password = await promptPassword('Password: ');
  }

  return { username, password };
}

/**
 * Auth command - login and save session
 */
program
  .command('auth')
  .description('Authenticate and save session')
  .requiredOption('--base-url <url>', 'Base URL of the API')
  .option('--session-file <path>', 'Path to session file')
  .option('--login-path <path>', 'Login endpoint path (default: /login)')
  .option('--auth-mode <mode>', 'Authentication mode: form or json (default: json)')
  .option('--username-field <field>', 'Username field name (default: username)')
  .option('--password-field <field>', 'Password field name (default: password)')
  .option('--debug', 'Enable debug logging')
  .action(async (options) => {
    try {
      console.log('Authenticating...');
      const credentials = await getCredentials();

      const config: ClientConfig = {
        baseUrl: options.baseUrl,
        sessionFile: options.sessionFile,
        debug: options.debug,
        auth: {
          mode: options.authMode || 'json',
          loginPath: options.loginPath,
          usernameField: options.usernameField,
          passwordField: options.passwordField,
          credentials,
        },
      };

      const client = new ProspectClient(config);
      await client.login(credentials);

      console.log('✓ Authentication successful');
      console.log(`Session saved to: ${client.getSessionFile()}`);
    } catch (err: any) {
      console.error('✗ Authentication failed:', err.message);
      process.exit(1);
    }
  });

/**
 * Set-cookies command - load cookies from file
 */
program
  .command('set-cookies')
  .description('Load cookies from Netscape or JSON file')
  .requiredOption('--cookies <file>', 'Path to cookies file')
  .option('--session-file <path>', 'Path to session file')
  .option('--base-url <url>', 'Base URL of the API (required for validation)')
  .option('--debug', 'Enable debug logging')
  .action(async (options) => {
    try {
      if (!options.baseUrl) {
        console.error('✗ --base-url is required');
        process.exit(1);
      }

      console.log(`Loading cookies from: ${options.cookies}`);

      const config: ClientConfig = {
        baseUrl: options.baseUrl,
        sessionFile: options.sessionFile,
        debug: options.debug,
      };

      const client = new ProspectClient(config);
      await client.loadCookies(options.cookies);

      console.log('✓ Cookies loaded successfully');
      console.log(`Session saved to: ${config.sessionFile || '~/.config/prospect-client/session.json'}`);
    } catch (err: any) {
      console.error('✗ Failed to load cookies:', err.message);
      process.exit(1);
    }
  });

/**
 * Search command - paginate and fetch data
 */
program
  .command('search')
  .description('Search and paginate results')
  .requiredOption('--base-url <url>', 'Base URL of the API')
  .requiredOption('--payload <file>', 'Path to JSON payload file')
  .requiredOption('--out <file>', 'Output file path')
  .option('--session-file <path>', 'Path to session file')
  .option('--max-pages <number>', 'Maximum pages to fetch', parseInt)
  .option('--max-items <number>', 'Maximum items to fetch', parseInt)
  .option('--page-size <number>', 'Override page size', parseInt)
  .option('--raw-pages <dir>', 'Save raw page responses to directory')
  .option('--debug', 'Enable debug logging')
  .action(async (options) => {
    try {
      console.log('Starting search...');

      // Load payload
      const payloadContent = await readFile(options.payload, 'utf-8');
      const payload: SearchPayload = JSON.parse(payloadContent);

      const config: ClientConfig = {
        baseUrl: options.baseUrl,
        sessionFile: options.sessionFile,
        debug: options.debug,
      };

      const client = new ProspectClient(config);

      const searchOptions = {
        maxPages: options.maxPages,
        maxItems: options.maxItems,
        pageSizeOverride: options.pageSize,
      };

      console.log('Fetching results...');
      console.log(`  Max pages: ${options.maxPages || '∞'}`);
      console.log(`  Max items: ${options.maxItems || '∞'}`);
      console.log(`  Page size: ${options.pageSize || payload.page_size || 'default'}`);

      const result = await client.searchAll(payload, searchOptions);

      // Save aggregated results
      await mkdir(dirname(options.out), { recursive: true });
      await writeFile(options.out, JSON.stringify(result.items, null, 2), 'utf-8');

      console.log('\n✓ Search complete');
      console.log(`  Items fetched: ${result.items.length}`);
      console.log(`  Pages fetched: ${result.pagesFetched}`);
      console.log(`  Total available: ${result.total} (${result.totalRelation})`);
      console.log(`  Output: ${options.out}`);

      // Save raw pages if requested
      if (options.rawPages) {
        console.log(`\nSaving raw pages to: ${options.rawPages}`);
        await mkdir(options.rawPages, { recursive: true });
        
        let pageNum = 0;
        for await (const item of client.searchStream(payload, searchOptions)) {
          // This is a simplified example - in practice you'd need to save whole page responses
          // For now, we'll just save items individually
          pageNum++;
        }
        console.log(`✓ Raw pages saved`);
      }
    } catch (err: any) {
      console.error('✗ Search failed:', err.message);
      if (options.debug) {
        console.error(err);
      }
      process.exit(1);
    }
  });

/**
 * Clear command - clear session
 */
program
  .command('clear')
  .description('Clear session and cookies')
  .option('--session-file <path>', 'Path to session file')
  .requiredOption('--base-url <url>', 'Base URL of the API')
  .action(async (options) => {
    try {
      const config: ClientConfig = {
        baseUrl: options.baseUrl,
        sessionFile: options.sessionFile,
      };

      const client = new ProspectClient(config);
      await client.clearSession();

      console.log('✓ Session cleared');
    } catch (err: any) {
      console.error('✗ Failed to clear session:', err.message);
      process.exit(1);
    }
  });

program
  .name('prospect-cli')
  .description('CLI for authenticated prospect search API')
  .version('1.0.0');

program.parse();
