import pino from 'pino';
import { mergeConfig } from './config.js';
import { SessionManager } from './session.js';
import { AuthManager } from './auth.js';
import { HttpClient } from './http.js';
import { SearchManager } from './search.js';
import type {
  ClientConfig,
  SearchPayload,
  SearchResult,
  SearchOptions,
  MergedClientConfig,
} from './types.js';

/**
 * Main client for interacting with the prospect search API
 */
export class ProspectClient {
  private config: MergedClientConfig;
  private logger: pino.Logger;
  private session: SessionManager;
  private auth: AuthManager | null = null;
  private http: HttpClient;
  private search: SearchManager;
  private sessionInitialized = false;

  constructor(config: ClientConfig) {
    this.config = mergeConfig(config);

    // Initialize logger with basic output (pino-pretty excluded from bundle)
    this.logger = pino({
      level: this.config.debug ? 'debug' : 'info',
    });

    // Initialize session manager
    this.session = new SessionManager(this.config.sessionFile, this.logger);

    // Initialize auth manager (if auth config provided)
    if (this.config.auth.credentials) {
      this.auth = new AuthManager(
        this.config.baseUrl,
        this.config.auth,
        this.session,
        this.logger
      );
    }

    // Initialize HTTP client
    this.http = new HttpClient(
      this.config.baseUrl,
      this.session,
      this.auth,
      this.config.headers,
      this.config.retries,
      this.config.rateLimit,
      this.logger
    );

    // Initialize search manager
    this.search = new SearchManager(this.http, this.logger);
  }

  /**
   * Ensure session is loaded (call this before making requests)
   */
  async ensureSession(): Promise<void> {
    if (this.sessionInitialized) {
      return;
    }

    await this.session.load();
    this.sessionInitialized = true;
  }

  /**
   * Manually trigger login and save session
   */
  async login(credentials?: { username: string; password: string }): Promise<void> {
    await this.ensureSession();
    
    if (!this.auth) {
      // Create auth manager if not exists
      this.auth = new AuthManager(
        this.config.baseUrl,
        this.config.auth,
        this.session,
        this.logger
      );
      
      // Update HTTP client with auth manager
      this.http = new HttpClient(
        this.config.baseUrl,
        this.session,
        this.auth,
        this.config.headers,
        this.config.retries,
        this.config.rateLimit,
        this.logger
      );
      
      // Update search manager with new HTTP client
      this.search = new SearchManager(this.http, this.logger);
    }
    
    await this.auth.login(credentials);
  }

  /**
   * Load cookies from a file (Netscape or JSON format)
   */
  async loadCookies(cookieFile: string): Promise<void> {
    await this.ensureSession();
    await this.session.loadCookiesFromFile(cookieFile);
    await this.session.save();
  }

  /**
   * Clear session and cookies
   */
  async clearSession(): Promise<void> {
    await this.session.clear();
    this.sessionInitialized = false;
  }

  /**
   * Search with pagination, returning all results
   */
  async searchAll(payload: SearchPayload, options?: SearchOptions): Promise<SearchResult> {
    await this.ensureSession();
    return this.search.searchAll(payload, options);
  }

  /**
   * Stream search results page by page
   */
  async *searchStream(
    payload: SearchPayload,
    options?: SearchOptions
  ): AsyncGenerator<any, void, unknown> {
    await this.ensureSession();
    yield* this.search.searchStream(payload, options);
  }

  /**
   * Get the logger instance
   */
  getLogger(): pino.Logger {
    return this.logger;
  }

  /**
   * Get the session file path
   */
  getSessionFile(): string {
    return this.config.sessionFile;
  }
}

// Export types and utilities
export * from './types.js';
export { mergeConfig } from './config.js';
export { buildNextPagePayload } from './search.js';
